<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Data\{KnowledgeContentData,KnowledgeSourceName};use App\Domain\AI\Knowledge\Enums\{KnowledgeSourceStatus,KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Models\{KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Support\CanonicalJsonHasher;use App\Models\User;use Illuminate\Support\Facades\DB;
final class CreateKnowledgeSourceService{public function __construct(private AiLifecycleAuthorization$auth,private CanonicalJsonHasher$hasher){}public function create(User$actor,string|KnowledgeSourceName$name,KnowledgeContentData$data):KnowledgeSource{$name=$name instanceof KnowledgeSourceName?$name:KnowledgeSourceName::from($name);return DB::transaction(function()use($actor,$name,$data){$a=$this->auth->authorize($actor);$source=new KnowledgeSource();$source->name=$name->value;$source->type=$data->type;$source->status=KnowledgeSourceStatus::Active;$source->created_by_user_id=$a->actorUserId;$source->save();$version=new KnowledgeSourceVersion();$version->knowledge_source_id=$source->id;$version->version_number=1;$version->status=KnowledgeVersionStatus::Draft;$version->content=$data->content;$version->checksum=$this->hasher->hash($data->content);$version->created_by_user_id=$a->actorUserId;$version->save();return$source->load('versions');});}}
